const $=s=>document.querySelector(s),money=n=>new Intl.NumberFormat('fa-IR').format(Math.round(Number(n)||0))+' تومان',pad=n=>String(n).padStart(2,'0');
function toJalali(gy,gm,gd){const g=[31,28,31,30,31,30,31,31,30,31,30,31],j=[31,31,31,31,31,31,30,30,30,30,30,29];let y=gy-1600,d=365*y+Math.floor((y+3)/4)-Math.floor((y+99)/100)+Math.floor((y+399)/400);for(let i=0;i<gm-1;i++)d+=g[i];if(gm>2&&((gy%4===0&&gy%100!==0)||gy%400===0))d++;d+=gd-1;let jd=d-79,jy=979+33*Math.floor(jd/12053);jd%=12053;jy+=4*Math.floor(jd/1461);jd%=1461;if(jd>=366){jy+=Math.floor((jd-1)/365);jd=(jd-1)%365}let i=0;while(i<11&&jd>=j[i])jd-=j[i++];return[jy,i+1,jd+1]}
function fmtJ(d){const j=toJalali(d.getFullYear(),d.getMonth()+1,d.getDate());return `${j[0]}/${pad(j[1])}/${pad(j[2])}`}function fmtG(d){return `${d.getFullYear()}/${pad(d.getMonth()+1)}/${pad(d.getDate())}`}function key(d){return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}function startOfWeek(d){const x=new Date(d),off=(x.getDay()+1)%7;x.setDate(x.getDate()-off);return x}function save(){localStorage.setItem(storageKey,JSON.stringify(state));if(currentUser){clearTimeout(syncTimer);syncTimer=setTimeout(syncAllEntries,500)}}function getData(k){if(!state[k])state[k]={tasks:[],expenses:[],note:''};return state[k]}function total(data){return data.expenses.reduce((s,e)=>s+(Number(e.amount)||0),0)}
function migrateLegacyDates(){if(localStorage.getItem('daily-local-date-v1'))return;Object.keys(state).forEach(oldKey=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(oldKey))return;const oldDate=new Date(oldKey+'T00:00:00'),localDate=new Date(oldDate);localDate.setDate(localDate.getDate()+1);const newKey=key(localDate);if(newKey!==oldKey){state[newKey]=state[newKey]?{tasks:[...state[newKey].tasks,...state[oldKey].tasks],expenses:[...state[newKey].expenses,...state[oldKey].expenses],note:state[newKey].note||state[oldKey].note}:state[oldKey];delete state[oldKey]}});save();localStorage.setItem('daily-local-date-v1','true')}
function recoverSep31Data(){if(localStorage.getItem('daily-sep31-recovery-v1'))return;const from='2026-10-02',to='2026-09-22';if(state[from]){const moved=state[from],existing=state[to];state[to]=existing?{tasks:[...existing.tasks,...moved.tasks],expenses:[...existing.expenses,...moved.expenses],note:existing.note||moved.note}:moved;delete state[from];save()}localStorage.setItem('daily-sep31-recovery-v1','true')}
function usernameToEmail(username){return `${username.trim().toLowerCase()}@dailyapp.example.com`}
function authMessage(text,type=''){const el=$('#authMessage');if(el){el.textContent=text;el.className=`auth-message ${type}`}}
function renderAuth(mode='login'){document.body.classList.remove('dark');$('#appShell').innerHTML=`<section class="auth-shell"><div class="auth-card"><div class="auth-brand"><div class="eyebrow">Cailo's To Do List</div><h1>Daily</h1><p>تقویم دیجیتال شخصی شما</p></div><div class="auth-tabs"><button class="${mode==='login'?'active':''}" id="loginTab">ورود</button><button class="${mode==='signup'?'active':''}" id="signupTab">ثبت‌نام</button></div><form id="authForm" class="auth-form">${mode==='signup'?`<label>شماره تلفن<input id="authPhone" inputmode="tel" placeholder="مثلاً ۰۹۱۲۱۲۳۴۵۶۷" required></label>`:''}<label>نام کاربری<input id="authUsername" autocomplete="username" placeholder="مثلاً cailo" required></label><label>رمز عبور<input id="authPassword" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" minlength="8" placeholder="حداقل ۸ کاراکتر" required></label><button class="auth-submit" type="submit">${mode==='login'?'ورود به Daily':'ساخت حساب کاربری'}</button></form><p id="authMessage" class="auth-message"></p><p class="auth-note">اطلاعات هر حساب فقط برای همان کاربر ذخیره و نمایش داده می‌شود.</p></div></section>`;$('#loginTab').onclick=()=>renderAuth('login');$('#signupTab').onclick=()=>renderAuth('signup');$('#authForm').onsubmit=e=>handleAuth(e,mode)}
async function handleAuth(event,mode){event.preventDefault();if(!supabaseClient){authMessage('اتصال دیتابیس تنظیم نشده است.','error');return}const username=$('#authUsername').value.trim().toLowerCase(),password=$('#authPassword').value,phone=$('#authPhone')?normalizeDigits($('#authPhone').value):'';if(!/^[a-z0-9._-]{3,24}$/.test(username)){authMessage('نام کاربری باید ۳ تا ۲۴ حرف انگلیسی، عدد، نقطه، خط تیره یا زیرخط باشد.','error');return}if(mode==='signup'&&phone.length<10){authMessage('شماره تلفن را کامل وارد کنید.','error');return}authMessage('در حال انجام…');const email=usernameToEmail(username);if(mode==='signup'){const {error:signupError}=await supabaseClient.functions.invoke('daily-signup',{body:{username,password,phone}});if(signupError){let message=signupError.message;try{message=(await signupError.context.json()).error||message}catch{}authMessage(message,'error');return}}const result=await supabaseClient.auth.signInWithPassword({email,password});if(result.error){authMessage(result.error.message,'error');return}await beginUserSession(result.data.user)}
async function syncAllEntries(){if(!currentUser||!supabaseClient)return;const entries=Object.entries(state).map(([entry_date,v])=>({user_id:currentUser.id,entry_date,tasks:v.tasks||[],expenses:v.expenses||[],note:v.note||'',updated_at:new Date().toISOString()}));if(!entries.length)return;const {error}=await supabaseClient.from('daily_entries').upsert(entries,{onConflict:'user_id,entry_date'});if(error)console.error('Daily sync error',error)}
async function loadCloudEntries(){const {data:rows,error}=await supabaseClient.from('daily_entries').select('entry_date,tasks,expenses,note').eq('user_id',currentUser.id);if(error)throw error;const cloud={};(rows||[]).forEach(r=>cloud[r.entry_date]={tasks:r.tasks||[],expenses:r.expenses||[],note:r.note||''});return cloud}
async function beginUserSession(user){currentUser=user;let cloud;try{cloud=await loadCloudEntries()}catch(error){renderAuth();authMessage('اتصال دیتابیس برقرار نشد. ابتدا اسکریپت SQL را اجرا کنید.','error');return}const isOwner=(user.user_metadata?.username||'').toLowerCase()==='cailo';if(!Object.keys(cloud).length&&isOwner&&Object.keys(legacyState).length){state=JSON.parse(JSON.stringify(legacyState));await syncAllEntries()}else state=cloud;save();renderHome()}
function showSyncToast(){document.querySelector('.sync-toast')?.remove();const toast=document.createElement('div');toast.className='sync-toast';toast.innerHTML='<span>✓</span> با موفقیت به‌روز رسانی شد';document.body.appendChild(toast);setTimeout(()=>toast.classList.add('show'),20);setTimeout(()=>{toast.classList.remove('show');setTimeout(()=>toast.remove(),260)},2800)}
async function refreshCloud(){const button=$('#refreshBtn');if(button){button.classList.add('syncing');button.title='در حال همگام‌سازی…'}try{await syncAllEntries();state=await loadCloudEntries();localStorage.setItem(storageKey,JSON.stringify(state));renderHome();showSyncToast()}catch(error){alert('همگام‌سازی انجام نشد. اتصال اینترنت را بررسی کن.')}finally{button?.classList.remove('syncing')}}
async function signOut(){await supabaseClient.auth.signOut();currentUser=null;state={};renderAuth()}
async function changePassword(){const password=prompt('رمز عبور جدید را وارد کن (حداقل ۸ کاراکتر):');if(password===null)return;if(password.length<8){alert('رمز عبور باید حداقل ۸ کاراکتر باشد.');return}const confirmPassword=prompt('رمز عبور جدید را دوباره وارد کن:');if(password!==confirmPassword){alert('دو رمز عبور یکسان نیستند.');return}const {error}=await supabaseClient.auth.updateUser({password});if(error){alert(error.message);return}alert('رمز عبور با موفقیت تغییر کرد.')}
async function initializeApp(){migrateLegacyDates();recoverSep31Data();legacyState=JSON.parse(JSON.stringify(state));if(localStorage.getItem('daily-theme')==='dark')document.body.classList.add('dark');if('serviceWorker' in navigator)navigator.serviceWorker.register('service-worker.js');if(!supabaseClient){renderAuth();authMessage('پیکربندی اتصال دیتابیس پیدا نشد.','error');return}const {data:{session}}=await supabaseClient.auth.getSession();if(session)await beginUserSession(session.user);else renderAuth()}
function visibleDays(){const start=viewMode==='week'?startOfWeek(cursor):new Date(cursor);return Array.from({length:viewMode==='week'?7:1},(_,i)=>{const d=new Date(start);d.setDate(start.getDate()+i);return d})}
function jalaliMonthTotal(base){const target=toJalali(base.getFullYear(),base.getMonth()+1,base.getDate());return Object.entries(state).reduce((sum,[k,value])=>{const [y,m,d]=k.split('-').map(Number),j=toJalali(y,m,d);return j[0]===target[0]&&j[1]===target[1]?sum+total(value):sum},0)}
function header(){const unread=localStorage.getItem('daily-last-update')!=='۲.۱.۹',username=currentUser?.user_metadata?.username||'کاربر';return `<header class="topbar"><div class="brand"><div class="eyebrow">Cailo's To Do List</div><div class="brand-subtitle">تقویم دیجیتال کایلو</div><h1>برنامه و هزینه‌های من</h1><p class="muted">امروز: ${fmtJ(new Date())} | ${new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(new Date())}</p></div><div class="top-actions"><div class="account-chip" title="حساب کاربری">${username}</div><button id="changePasswordBtn" class="change-password-btn" title="تغییر رمز عبور">رمز جدید</button><button id="signOutBtn" class="signout-btn" title="خروج از حساب">خروج</button><div class="view-toggle"><button id="weekViewBtn" class="${viewMode==='week'?'active':''}">هفته</button><button id="todayViewBtn" class="${viewMode==='today'?'active':''}">امروز</button></div><button id="themeBtn" class="theme-switch" title="تغییر تم"><span class="theme-sun">☼</span><span class="theme-moon">☾</span><i></i></button><button id="refreshBtn" class="tool-btn icon-button" title="همگام‌سازی"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 11a8 8 0 1 0 2 5.3M20 4v7h-7"/></svg></button><button id="calendarBtn" class="tool-btn icon-button" title="تقویم"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4M17 3v4M3 10h18M8 14h3M14 14h2M8 18h2"/></svg></button><button id="reportBtn" class="tool-btn icon-button" title="گزارش"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20V10M10 20V4M16 20v-7M22 20H2"/></svg></button><button id="updatesBtn" class="tool-btn update-btn" title="جزئیات بروزرسانی‌ها">ⓘ${unread?'<i></i>':''}</button></div></header>`}
function bindHeader(){ $('#weekViewBtn').onclick=()=>{viewMode='week';localStorage.setItem('daily-view',viewMode);renderHome()};$('#todayViewBtn').onclick=()=>{viewMode='today';cursor=new Date();cursor.setHours(0,0,0,0);localStorage.setItem('daily-view',viewMode);renderHome()};$('#refreshBtn').onclick=refreshCloud;$('#themeBtn').onclick=toggleTheme;$('#changePasswordBtn').onclick=changePassword;$('#signOutBtn').onclick=signOut;$('#calendarBtn').onclick=()=>{document.querySelector('#calendarModal').classList.remove('hidden');buildCalendar()};$('#reportBtn').onclick=()=>{page='report';renderReport()};$('#updatesBtn').onclick=showUpdates;document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>document.querySelector('#'+x.dataset.close).classList.add('hidden'));$('#prevMonth').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()-1);buildCalendar()};$('#nextMonth').onclick=()=>{calendarCursor.setMonth(calendarCursor.getMonth()+1);buildCalendar()}}
function calendarMarkup(){return `<div class="modal hidden" id="calendarModal"><div class="modal-card"><div class="modal-head"><h2>تقویم</h2><button class="close-btn" data-close="calendarModal">×</button></div><div class="calendar-nav"><button id="prevMonth">‹</button><strong id="calendarMonth"></strong><button id="nextMonth">›</button></div><div class="calendar-grid" id="calendarGrid"></div></div></div><div class="modal hidden" id="dayPreviewModal"><div class="modal-card day-preview"><div class="modal-head"><div><h2 id="previewTitle"></h2><p class="muted" id="previewDate"></p></div><button class="close-btn" data-close="dayPreviewModal">×</button></div><div class="preview-section"><h3>کارهای روز</h3><div id="previewTasks"></div></div><div class="preview-section"><h3>هزینه‌های روز</h3><div id="previewExpenses"></div><div id="previewTotal" class="preview-total"></div></div><div class="preview-section"><h3>یادداشت روزانه</h3><p id="previewNote" class="preview-note"></p></div><button id="previewEditBtn" class="back-btn">مشاهده و ویرایش روز</button></div></div>`}
function classifyExpense(text){const value=String(text||'').toLowerCase();if(/قهوه|کافه|اسپرسو|لاته|کاپوچینو/.test(value))return 'کافه و رستوران';if(/اسنپ|تپسی/.test(value))return 'اسنپ';if(/سوپر|نان|میوه|لبنیات/.test(value))return 'سوپرمارکت';if(/فست|پیتزا|برگر|ساندویچ/.test(value))return 'فست فود';if(/رستوران|غذا|ناهار|شام/.test(value))return 'رستوران';if(/دارو|دکتر|درمان/.test(value))return 'درمان';if(/قبض|اینترنت|شارژ/.test(value))return 'قبوض';return 'سایر'}function currentMonthExpenses(){const current=toJalali(cursor.getFullYear(),cursor.getMonth()+1,cursor.getDate());return Object.entries(state).flatMap(([date,data])=>{const [year,month,day]=date.split('-').map(Number),jalali=toJalali(year,month,day);return jalali[0]===current[0]&&jalali[1]===current[1]?expensesFromData(data,fmtJ(new Date(year,month-1,day))):[]})}async function askCloudDailyAI(message){if(!supabaseClient||!currentUser)throw new Error('برای هوش مصنوعی آنلاین باید وارد حساب کاربری شوی.');const result=await supabaseClient.functions.invoke('daily-ai',{body:{message:message,date:key(cursor),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone||'Asia/Tehran'}});if(result.error)throw result.error;if(result.data?.error)throw new Error(result.data.error);return result.data}function applyCloudActions(actions){if(!Array.isArray(actions)||!actions.length)return false;const data=getData(key(cursor));let changed=false;actions.forEach(action=>{if(action?.type==='add_expense'&&Number(action.amount)>0){data.expenses.push({desc:String(action.description||'هزینه جدید'),amount:Number(action.amount),category:String(action.category||'سایر')});changed=true}else if(action?.type==='add_task'&&String(action.text||'').trim()){data.tasks.push({text:String(action.text).trim(),duration:String(action.duration||''),done:false,starred:!!action.starred});changed=true}else if(action?.type==='complete_task'&&String(action.query||'').trim()){const task=(data.tasks||[]).find(item=>!item.done&&String(item.text||'').includes(String(action.query).trim()));if(task){task.done=true;changed=true}}});if(changed)save();return changed}
function assistantHelp(){return 'می‌توانی بنویسی: «۲۳۹ قهوه»، «کار: مطالعه ۲ ساعت»، «انجام کن: مطالعه»، «خرج امروز چقدر است؟»، «کارهای مهمم کدام‌اند؟» یا «این ماه بیشترین خرجم چی بوده؟».'}function assistantTasks(data,filter){return (data.tasks||[]).filter(task=>task.text).filter(filter||(()=>true))}function assistantWeekTotal(){return Array.from({length:7},(_,i)=>{const d=startOfWeek(cursor);d.setDate(d.getDate()+i);return total(getData(key(d)))}).reduce((sum,value)=>sum+value,0)}function assistantTop(expenses){const groups={};expenses.forEach(expense=>groups[expense.category||'سایر']=(groups[expense.category||'سایر']||0)+Number(expense.amount||0));return Object.entries(groups).sort((a,b)=>b[1]-a[1])[0]||[]}function assistantReply(message){const input=String(message||'').trim(),digits=normalizeDigits(input),data=getData(key(cursor));if(!input||/راهنما|کمک|قابلیت/.test(input))return assistantHelp();if(/تاریخ.*امروز|امروز.*تاریخ/.test(input))return 'تاریخ انتخاب‌شده: '+fmtJ(cursor)+' برابر با '+fmtG(cursor)+'.';if(/کار.*مهم|مهم.*کار|ستاره/.test(input)){const tasks=assistantTasks(data,t=>t.starred);return tasks.length?'کارهای مهم امروز: '+tasks.map(t=>'«'+t.text+'»').join('، ')+'.':'برای امروز هنوز کار ستاره‌دار نداری.'}if(/انجام نشده|باقی.*کار|کار.*باقی/.test(input)){const tasks=assistantTasks(data,t=>!t.done);return tasks.length?'کارهای باقی‌مانده: '+tasks.map(t=>'«'+t.text+'»').join('، ')+'.':'آفرین؛ تمام کارهای امروز انجام شده‌اند.'}if(/کارهای امروز|برنامه امروز|چه کار.*دارم|کار.*دارم/.test(input)){const tasks=assistantTasks(data);return tasks.length?'برای امروز '+new Intl.NumberFormat('fa-IR').format(tasks.length)+' کار داری: '+tasks.map(t=>(t.done?'✓ ':'○ ')+t.text).join('، ')+'.':'امروز هنوز کاری ثبت نکرده‌ای.'}if(/زمان.*کار|چند ساعت|چقدر زمان/.test(input))return 'جمع زمان موردنیاز کارهای امروز '+hoursLabel(dayTaskHours(data))+' است.';if(/خرج.*امروز|هزینه.*امروز|مبلغ.*امروز/.test(input))return 'جمع هزینه‌های امروز '+money(total(data))+' است.';if(/خرج.*هفته|هزینه.*هفته|مبلغ.*هفته/.test(input))return 'جمع هزینه‌های این هفته '+money(assistantWeekTotal())+' است.';if(/خرج.*ماه|هزینه.*ماه|مبلغ.*ماه|جمع.*ماه/.test(input))return 'جمع هزینه‌های این ماه '+money(jalaliMonthTotal(cursor))+' است.';if(/بیشترین.*خرج|بیشترین.*هزینه|بیشتر.*خرج/.test(input)){const top=assistantTop(currentMonthExpenses());return top[0]?'بیشترین خرج این ماه در دسته «'+top[0]+'» بوده؛ جمعاً '+money(top[1])+' هزینه کرده‌ای.':'هنوز برای این ماه هزینه‌ای ثبت نشده است.'}if(/دسته.*هزینه|دسته بندی|گزارش.*دسته/.test(input)){const groups={};currentMonthExpenses().forEach(e=>groups[e.category||'سایر']=(groups[e.category||'سایر']||0)+Number(e.amount||0));const list=Object.entries(groups).sort((a,b)=>b[1]-a[1]).slice(0,5);return list.length?'دسته‌بندی‌های اصلی این ماه: '+list.map(([c,v])=>c+' ('+money(v)+')').join('، ')+'.':'هنوز هزینه‌ای برای این ماه ثبت نشده است.'}const done=input.match(/(?:انجام کن|تکمیل کن|تمام کن)s*[:：-]?s*(.+)/);if(done){const task=assistantTasks(data,t=>!t.done&&t.text.includes(done[1].trim()))[0];if(task){task.done=true;save();return 'کار «'+task.text+'» انجام‌شده علامت خورد.'}return 'کاری با این عنوان در کارهای انجام‌نشدهٔ امروز پیدا نکردم.'}const addTask=input.match(/(?:کار|تسک)s*[:：-]s*(.+)/);if(addTask){const value=addTask[1].trim(),duration=value.match(/([۰-۹٠-٩0-9]+)s*ساعت/),text=value.replace(/([۰-۹٠-٩0-9]+)s*ساعت/g,'').trim();if(text){data.tasks.push({text,duration:duration?duration[0]:'',done:false,starred:false});save();return 'کار «'+text+'»'+(duration?' با زمان '+duration[0]:'')+' برای امروز ثبت شد.'}}const raw=Number(digits);if(raw>0){const amount=raw<10000?raw*1000:raw,description=input.replace(/[۰-۹٠-٩0-9٬,،.]/g,'').replace(/(?:ثبت|اضافه|هزینه|خرج)/g,'').trim()||'هزینه جدید',category=classifyExpense(description);data.expenses.push({desc:description,amount,category});save();return 'ثبت شد: «'+description+'» به مبلغ '+money(amount)+' در دسته «'+category+'» برای '+fmtJ(cursor)+'.'}return 'درخواست را متوجه نشدم. '+assistantHelp()}
function assistantMarkup(){return '<section class="daily-assistant"><button id="assistantOpen" class="assistant-search"><span class="assistant-spark">✦</span><span>از Daily بپرس یا سریع هزینه ثبت کن…</span><kbd>⌕</kbd></button></section><div class="modal hidden" id="assistantModal"><div class="modal-card assistant-modal"><div class="modal-head"><div><h2>دستیار Daily</h2><p class="muted">مثلاً: ۲۳۹ قهوه، «کار: مطالعه ۲ ساعت» یا یک پرسش دربارهٔ گزارش‌ها</p></div><button class="close-btn" data-close="assistantModal">×</button></div><div id="assistantMessages" class="assistant-messages"><div class="assistant-bubble bot">سلام! می‌توانم هزینه را برای امروز ثبت کنم یا از داده‌های خودت گزارش بدهم.</div></div><form id="assistantForm" class="assistant-form"><input id="assistantInput" autocomplete="off" placeholder="پیام خودت را بنویس…"><button type="submit">ارسال</button></form></div></div>'}function bindAssistant(){const modal=$('#assistantModal'),open=()=>{modal.classList.remove('hidden');setTimeout(()=>$('#assistantInput')?.focus(),80)};$('#assistantOpen').onclick=open;document.querySelectorAll('[data-close="assistantModal"]').forEach(button=>button.onclick=()=>modal.classList.add('hidden'));$('#assistantForm').onsubmit=async event=>{event.preventDefault();const input=$('#assistantInput'),text=input.value.trim();if(!text)return;const messages=$('#assistantMessages'),user=document.createElement('div');user.className='assistant-bubble user';user.textContent=text;messages.appendChild(user);const reply=document.createElement('div');reply.className='assistant-bubble bot';reply.textContent='در حال فکر کردن…';messages.appendChild(reply);input.value='';messages.scrollTop=messages.scrollHeight;try{const cloud=await askCloudDailyAI(text);applyCloudActions(cloud.actions);reply.textContent=cloud.reply||assistantReply(text)}catch(error){reply.textContent=assistantReply(text)}messages.scrollTop=messages.scrollHeight}}function bindSwipe(){const surface=$('#days');if(!surface)return;let startX=0,startY=0;surface.addEventListener('touchstart',event=>{const touch=event.touches[0];startX=touch.clientX;startY=touch.clientY},{passive:true});surface.addEventListener('touchend',event=>{const touch=event.changedTouches[0],dx=touch.clientX-startX,dy=touch.clientY-startY;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy))return;const step=viewMode==='week'?7:1;cursor.setDate(cursor.getDate()+(dx<0?step:-step));renderHome()},{passive:true})}
function renderHome(){page='home';const days=visibleDays(),today=getData(key(new Date())),weekDays=Array.from({length:7},(_,i)=>{const d=startOfWeek(cursor);d.setDate(d.getDate()+i);return d}),weekTotal=weekDays.reduce((s,d)=>s+total(getData(key(d))),0),monthTotal=jalaliMonthTotal(cursor),rangeTitle=viewMode==='week'?fmtJ(days[0])+' تا '+fmtJ(days[6]):fmtJ(days[0]);$('#appShell').innerHTML=header()+'<section class="summary-grid"><article class="summary-card blue-card"><span>هزینه امروز</span><strong>'+money(total(today))+'</strong></article><article class="summary-card"><span>هزینه این هفته</span><strong>'+money(weekTotal)+'</strong></article><article class="summary-card"><span>هزینه این ماه</span><strong>'+money(monthTotal)+'</strong></article></section>'+assistantMarkup()+'<section class="week-switcher"><button class="soft-btn" id="prevWeek">هفته قبل</button><div class="week-title">'+rangeTitle+'</div><button class="soft-btn" id="nextWeek">هفته بعد</button></section><section class="days" id="days"></section>'+calendarMarkup();const wrap=$('#days');wrap.classList.toggle('today-mode',viewMode==='today');days.forEach(d=>{const data=getData(key(d)),node=document.importNode($('#daySummaryTemplate').content,true),card=node.querySelector('.day-card');card.classList.toggle('today-focus',viewMode==='today');card.querySelector('.day-name').textContent=new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d);card.querySelector('.day-date').textContent=fmtJ(d)+' · '+fmtG(d);card.querySelector('.day-total').textContent=money(total(data));const tasks=card.querySelector('.tasks-summary'),activeTasks=data.tasks.filter(t=>t.text);const taskLabel=card.querySelector('.section-label');taskLabel.innerHTML='کارهای روز <span class="card-task-hours">'+hoursLabel(dayTaskHours(data))+'</span>'; if(activeTasks.length)activeTasks.slice(0,4).forEach(t=>{const item=document.createElement('div');item.className='summary-item'+(t.done?' done':'');item.innerHTML='<span class="task-summary-text">'+(t.starred?'★ ':'')+(t.done?'✓ ':'○ ')+escapeHtml(t.text)+'</span>'+(t.duration?'<span class="task-summary-duration">'+escapeHtml(t.duration)+'</span>':'');tasks.appendChild(item)});else tasks.innerHTML='<div class="summary-item">کاری ثبت نشده</div>';const expenses=card.querySelector('.expenses-summary'),activeExpenses=data.expenses.filter(e=>e.desc||e.amount);if(activeExpenses.length)activeExpenses.slice(0,3).forEach(e=>{const item=document.createElement('div');item.className='summary-item expense-summary';item.innerHTML='<span>'+String(e.desc||'هزینه')+'</span><strong>'+money(e.amount)+'</strong>';expenses.appendChild(item)});else expenses.innerHTML='<div class="summary-item">هزینه‌ای ثبت نشده</div>';card.onclick=()=>showDayPreview(d);card.querySelector('.open-day').onclick=event=>{event.stopPropagation();activeDate=new Date(d);page='day';renderDay()};wrap.appendChild(node)});$('#prevWeek').onclick=()=>{cursor.setDate(cursor.getDate()-7);renderHome()};$('#nextWeek').onclick=()=>{cursor.setDate(cursor.getDate()+7);renderHome()};bindHeader();bindAssistant();bindSwipe()}
const categoryStorageKey='daily-expense-categories-v1',defaultExpenseCategories=['سوپرمارکت','فست فود','اسنپ','رستوران','قبوض','خرید','تفریح','درمان','سایر'];function expenseCategories(){try{const saved=JSON.parse(localStorage.getItem(categoryStorageKey)||'[]'),used=Object.values(state).flatMap(day=>(day.expenses||[]).map(expense=>expense.category).filter(Boolean));return [...new Set([...defaultExpenseCategories,...saved,...used])]}catch{return defaultExpenseCategories}}function saveExpenseCategory(category){const clean=String(category||'').trim();if(!clean)return null;const all=expenseCategories();if(!all.includes(clean))localStorage.setItem(categoryStorageKey,JSON.stringify([...all.slice(defaultExpenseCategories.length),clean]));return clean}function buildCategorySelect(value){const select=document.createElement('select');select.className='category-pill';expenseCategories().forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;option.selected=(value||'سایر')===category;select.appendChild(option)});const add=document.createElement('option');add.value='__new__';add.textContent='＋ افزودن دسته';select.appendChild(add);select.onchange=()=>{if(select.value!=='__new__')return;const created=saveExpenseCategory(prompt('نام دسته‌بندی جدید را وارد کن:'));if(created){const options=expenseCategories();select.innerHTML='';options.forEach(category=>{const option=document.createElement('option');option.value=category;option.textContent=category;option.selected=category===created;select.appendChild(option)});const plus=document.createElement('option');plus.value='__new__';plus.textContent='＋ افزودن دسته';select.appendChild(plus);select.dispatchEvent(new Event('categorychange'))}else select.value=value||'سایر'};return select}function categoryOptionsHtml(selected){return expenseCategories().map(category=>'<option value="'+category.replace(/"/g,'&quot;')+'" '+((selected||'سایر')===category?'selected':'')+'>'+category+'</option>').join('')+'<option value="__new__">＋ افزودن دسته</option>'}
function durationHours(value){const text=normalizeDigits(value||'');const found=text.match(/\d+(?:\.\d+)?/);return found?Number(found[0])||0:0}function dayTaskHours(data){return (data.tasks||[]).reduce((sum,task)=>sum+durationHours(task.duration),0)}function hoursLabel(value){const hours=Number(value)||0;return new Intl.NumberFormat('fa-IR',{maximumFractionDigits:1}).format(hours)+' ساعت'}function escapeHtml(value){return String(value||'').replace(/[&<>"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[char]))}
function normalizeDigits(v){return String(v).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/[^0-9]/g,'')}
function deleteButton(action){const btn=document.createElement('button');btn.type='button';btn.className='delete-btn';btn.title='حذف';btn.textContent='×';btn.onclick=e=>{e.preventDefault();e.stopPropagation();action()};return btn}
function playTaskTick(){try{const ding=new Audio('sounds/ding-sound-effect.mp3');ding.volume=.42;ding.play().catch(()=>{})}catch{}}
function taskEditor(t,data,index){const row=document.createElement('div');row.className='task-row'+(t.done?' completed-task':'');row.draggable=true;row.dataset.taskIndex=index;const grip=document.createElement('span');grip.className='drag-grip';grip.textContent='⋮⋮';grip.title='برای جابه‌جایی بکشید';const star=document.createElement('button');star.type='button';star.className='task-star'+(t.starred?' active':'');star.textContent=t.starred?'★':'☆';star.title='کار مهم';star.onclick=()=>{t.starred=!t.starred;save();renderDay()};const box=document.createElement('input');box.type='checkbox';box.checked=!!t.done;box.setAttribute('aria-label','انجام شد');box.onchange=()=>{t.done=box.checked;row.classList.toggle('completed-task',t.done);if(t.done){row.classList.add('task-checked');playTaskTick();setTimeout(()=>{save();renderDay()},420)}else save()};const input=document.createElement('input');input.type='text';input.placeholder='شرح کار روز';input.value=t.text||'';input.oninput=()=>{t.text=input.value;save()};const duration=document.createElement('input');duration.type='text';duration.className='task-duration';duration.placeholder='🕒 زمان مورد نیاز';duration.value=t.duration||'';duration.oninput=()=>{t.duration=duration.value;save();$('#taskHours')&&( $('#taskHours').textContent=hoursLabel(dayTaskHours(data)) )};row.addEventListener('dragstart',e=>{e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(index));row.classList.add('dragging')});row.addEventListener('dragend',()=>row.classList.remove('dragging'));row.append(grip,star,box,input,duration,deleteButton(()=>{data.tasks.splice(index,1);save();renderDay()}));return row}
function expenseEditor(e,data,index){const row=document.createElement('div');row.className='expense-row';const descWrap=document.createElement('div');descWrap.className='expense-desc-wrap';const desc=document.createElement('input');desc.placeholder='شرح هزینه';desc.value=e.desc||'';desc.oninput=()=>{e.desc=desc.value;save()};const category=buildCategorySelect(e.category||'سایر');category.addEventListener('categorychange',()=>{e.category=category.value;save()});category.addEventListener('change',()=>{if(category.value!=='__new__'){e.category=category.value;save()}});descWrap.append(desc,category);const wrapper=document.createElement('div');wrapper.className='amount-wrap';const amount=document.createElement('input');amount.className='amount';amount.type='text';amount.inputMode='numeric';amount.autocomplete='off';amount.placeholder='مبلغ';amount.value=e.amount?new Intl.NumberFormat('fa-IR').format(e.amount):'';amount.oninput=()=>{const normalized=normalizeDigits(amount.value);amount.value=normalized?new Intl.NumberFormat('fa-IR').format(normalized):'';e.amount=normalized;save();$('#detailTotal').textContent='کل: '+money(total(data))};const unit=document.createElement('span');unit.textContent='تومان';wrapper.append(amount,unit);row.append(descWrap,wrapper,deleteButton(()=>{data.expenses.splice(index,1);save();renderDay()}));return row}
function entryModalMarkup(){return '<div class="modal hidden" id="taskEntryModal"><div class="modal-card entry-modal"><div class="modal-head"><h2>افزودن کار جدید</h2><button class="close-btn" data-close="taskEntryModal">×</button></div><form id="taskEntryForm" class="entry-form"><label>شرح کار<input id="newTaskText" type="text" placeholder="مثلاً تماس با مشتری" required></label><label>زمان مورد نیاز<input id="newTaskDuration" type="text" placeholder="مثلاً ۲ ساعت"></label><button class="entry-submit" type="submit">افزودن کار</button></form></div></div><div class="modal hidden" id="expenseEntryModal"><div class="modal-card entry-modal"><div class="modal-head"><h2>افزودن هزینه جدید</h2><button class="close-btn" data-close="expenseEntryModal">×</button></div><form id="expenseEntryForm" class="entry-form"><label>شرح هزینه<input id="newExpenseDesc" type="text" placeholder="مثلاً خرید روزانه" required></label><label>مبلغ (تومان)<input id="newExpenseAmount" type="text" inputmode="numeric" placeholder="مثلاً ۲۵۰٬۰۰۰" required></label><label>دسته‌بندی<select id="newExpenseCategory" class="category-select">'+categoryOptionsHtml('سایر')+'</select></label><button class="entry-submit" type="submit">افزودن مبلغ</button></form></div></div>'}
function renderDay(){const d=activeDate||new Date(),data=getData(key(d));$('#appShell').innerHTML='<section class="detail-page"><div class="page-head"><div><div class="eyebrow">Daily</div><h2>'+new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d)+' · '+fmtJ(d)+'</h2><p class="muted">'+fmtG(d)+'</p></div><div class="page-actions"><button id="themeBtn" class="tool-btn">☾</button><button id="backBtn" class="back-btn">بازگشت به هفته</button></div></div><div class="editor-grid"><section class="editor-card"><div class="section-label task-section-label">کارهای روز <span id="taskHours" class="task-hours">'+hoursLabel(dayTaskHours(data))+'</span><span class="drag-help">برای اولویت‌بندی بکشید و رها کنید</span></div><div id="taskEditor"></div><button id="addTask" class="add-entry-btn">＋ افزودن کار</button></section><section class="editor-card"><div class="section-label">هزینه‌های روز</div><div id="expenseEditor"></div><button id="addExpense" class="add-entry-btn">＋ افزودن مبلغ</button><div class="detail-total" id="detailTotal">کل: '+money(total(data))+'</div><textarea id="note" class="note" rows="4" placeholder="یادداشت روزانه...">'+(data.note||'')+'</textarea></section></div></section>'+entryModalMarkup();const t=$('#taskEditor'),e=$('#expenseEditor');data.tasks.forEach((x,i)=>t.appendChild(taskEditor(x,data,i)));t.addEventListener('dragover',ev=>{ev.preventDefault();const target=ev.target.closest('.task-row');if(target)target.classList.add('drop-target')});t.addEventListener('dragleave',ev=>ev.target.closest('.task-row')?.classList.remove('drop-target'));t.addEventListener('drop',ev=>{ev.preventDefault();const target=ev.target.closest('.task-row');document.querySelectorAll('.drop-target').forEach(x=>x.classList.remove('drop-target'));const from=Number(ev.dataTransfer.getData('text/plain')),to=target?Number(target.dataset.taskIndex):data.tasks.length-1;if(Number.isNaN(from)||Number.isNaN(to)||from===to)return;const moved=data.tasks.splice(from,1)[0];data.tasks.splice(to,0,moved);save();renderDay()});data.expenses.forEach((x,i)=>e.appendChild(expenseEditor(x,data,i)));$('#addTask').onclick=()=>$('#taskEntryModal').classList.remove('hidden');$('#addExpense').onclick=()=>$('#expenseEntryModal').classList.remove('hidden');document.querySelectorAll('[data-close]').forEach(x=>x.onclick=()=>$('#'+x.dataset.close).classList.add('hidden'));$('#taskEntryForm').onsubmit=event=>{event.preventDefault();data.tasks.push({text:$('#newTaskText').value.trim(),duration:$('#newTaskDuration').value.trim(),done:false});save();renderDay()};const entryCategory=$('#newExpenseCategory');entryCategory.onchange=()=>{if(entryCategory.value==='__new__'){const created=saveExpenseCategory(prompt('نام دسته‌بندی جدید را وارد کن:'));entryCategory.innerHTML=categoryOptionsHtml(created||'سایر')}};$('#expenseEntryForm').onsubmit=event=>{event.preventDefault();const amount=normalizeDigits($('#newExpenseAmount').value),category=entryCategory.value==='__new__'?'سایر':entryCategory.value;data.expenses.push({desc:$('#newExpenseDesc').value.trim(),amount,category});save();renderDay()};$('#note').oninput=x=>{data.note=x.target.value;save()};$('#backBtn').onclick=renderHome;$('#themeBtn').onclick=toggleTheme}
function expensesFromData(data,dateLabel){return (data.expenses||[]).filter(e=>e.desc||e.amount).map(e=>({desc:e.desc||'هزینه',amount:Number(e.amount)||0,category:e.category||'سایر',date:dateLabel||''}))}
function chartHtml(items,scope){const max=Math.max(...items.map(x=>x.value),1);return items.map((x,index)=>{const h=Math.max(3,x.value/max*210);return `<button type="button" class="bar-item report-bar" data-scope="${scope}" data-index="${index}"><small class="chart-value" data-value="${x.value}">۰</small><div class="bar" style="--bar-height:${h}px"></div><span>${x.label}</span></button>`}).join('')}
function animateCounter(el,value){const start=performance.now(),duration=760;const step=now=>{const ratio=Math.min((now-start)/duration,1),eased=1-Math.pow(1-ratio,3);el.textContent=new Intl.NumberFormat('fa-IR').format(Math.round(value*eased));if(ratio<1)requestAnimationFrame(step)};requestAnimationFrame(step)}
function animateCharts(){requestAnimationFrame(()=>document.querySelectorAll('.chart-value').forEach(el=>animateCounter(el,Number(el.dataset.value)||0)))}
function jalaliMonthWeeks(){const current=toJalali(cursor.getFullYear(),cursor.getMonth()+1,cursor.getDate()),jy=current[0],jm=current[1],groups=Array.from({length:5},(_,i)=>({label:`هفته ${i+1}`,value:0,expenses:[]}));Object.entries(state).forEach(([k,v])=>{const d=new Date(k+'T00:00:00'),j=toJalali(d.getFullYear(),d.getMonth()+1,d.getDate());if(j[0]===jy&&j[1]===jm){const group=groups[Math.floor((j[2]-1)/7)];group.value+=total(v);group.expenses.push(...expensesFromData(v,fmtJ(d)))}});return groups.filter((g,i)=>i<4||g.value>0)}
function animateCategoryValues(){requestAnimationFrame(()=>document.querySelectorAll('[data-category-value]').forEach(el=>{const value=Number(el.dataset.categoryValue)||0,start=performance.now(),duration=650;const step=now=>{const p=Math.min((now-start)/duration,1),eased=1-Math.pow(1-p,3);el.textContent=money(value*eased);if(p<1)requestAnimationFrame(step)};requestAnimationFrame(step)}))}
function showCategoryReport(item,title){document.querySelector('#categoryReportModal')?.remove();const expenses=item.expenses||[],groups={};expenses.forEach(expense=>{const category=expense.category||'سایر';if(!groups[category])groups[category]={total:0,items:[]};groups[category].total+=Number(expense.amount)||0;groups[category].items.push(expense)});const cards=Object.entries(groups).map(([category,group],index)=>'<article class="category-report-card" style="--delay:'+index*70+'ms"><div><span class="category-report-name">'+category+'</span><small>'+group.items.length+' هزینه</small></div><strong data-category-value="'+group.total+'">۰ تومان</strong><div class="category-expense-list">'+group.items.map(entry=>'<div><span>'+entry.desc+(entry.date?' · '+entry.date:'')+'</span><b>'+money(entry.amount)+'</b></div>').join('')+'</div></article>').join('')||'<div class="empty-category-report">برای این ستون هزینه‌ای ثبت نشده است.</div>';const modal=document.createElement('div');modal.className='modal';modal.id='categoryReportModal';modal.innerHTML='<div class="modal-card category-report-modal"><div class="modal-head"><div><h2>گزارش دسته‌بندی</h2><p class="muted">'+title+'</p></div><button class="close-btn" id="closeCategoryReport">×</button></div><div class="category-report-total">جمع این بازه <strong data-category-value="'+item.value+'">۰ تومان</strong></div><div class="category-report-grid">'+cards+'</div></div>';document.body.appendChild(modal);$('#closeCategoryReport').onclick=()=>modal.remove();animateCategoryValues()}
function reportDailyCategories(){const data=getData(key(cursor)),groups={};expensesFromData(data,fmtJ(cursor)).forEach(expense=>{if(!groups[expense.category])groups[expense.category]={label:expense.category,value:0,expenses:[]};groups[expense.category].value+=expense.amount;groups[expense.category].expenses.push(expense)});return Object.values(groups)}function reportRows(items){const totalValue=items.reduce((sum,item)=>sum+Number(item.value||0),0);return items.map((item,index)=>({n:index+1,label:item.label||'بدون عنوان',value:Number(item.value||0),share:totalValue?Math.round(Number(item.value||0)/totalValue*100):0}))}function exportExpenses(items){return items.flatMap(item=>(item.expenses||[]).map(expense=>({date:expense.date||fmtJ(cursor),category:expense.category||'سایر',desc:expense.desc||'هزینه',amount:Number(expense.amount||0)})))}function exportCategories(expenses){const groups={};expenses.forEach(expense=>{const name=expense.category||'سایر';groups[name]=(groups[name]||0)+expense.amount});return Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([label,value])=>({label,value}))}function exportTimeRows(title){const rows=[];const add=(label,data)=>{const value=dayTaskHours(data);if(value)rows.push({label,value})};if(title.includes('ماه')){const j=toJalali(cursor.getFullYear(),cursor.getMonth()+1,cursor.getDate());Object.entries(state).forEach(([date,data])=>{const [y,m,d]=date.split('-').map(Number),jd=toJalali(y,m,d);if(jd[0]===j[0]&&jd[1]===j[1]){const week=Math.floor((jd[2]-1)/7)+1;const found=rows.find(row=>row.label==='هفته '+week);if(found)found.value+=dayTaskHours(data);else add('هفته '+week,data)}})}else if(title.includes('هفته')){Array.from({length:7},(_,i)=>{const d=startOfWeek(cursor);d.setDate(d.getDate()+i);add(dayNames[i],getData(key(d)))})}else{(getData(key(cursor)).tasks||[]).filter(task=>task.text).forEach(task=>{const value=durationHours(task.duration);if(value)rows.push({label:task.text,value})})}return rows}function timeChart(rows){const max=Math.max(...rows.map(row=>row.value),1);return rows.map(row=>'<div class="time-row"><span>'+escapeHtml(row.label)+'</span><div class="time-track"><i style="width:'+Math.max(4,row.value/max*100)+'%"></i></div><b>'+hoursLabel(row.value)+'</b></div>').join('')||'<p class="empty">برای این بازه زمان موردنیاز کاری ثبت نشده است.</p>'}function professionalReport(title,items){const rows=reportRows(items),sum=rows.reduce((n,row)=>n+row.value,0),expenses=exportExpenses(items),categories=exportCategories(expenses),timeRows=exportTimeRows(title),categoryRows=categories.map((row,index)=>'<tr><td>'+new Intl.NumberFormat('fa-IR').format(index+1)+'</td><td><span class="tag">'+escapeHtml(row.label)+'</span></td><td>'+money(row.value)+'</td></tr>').join('')||'<tr><td colspan="3">جزئیات هزینه‌ای برای این بازه ثبت نشده است.</td></tr>',detailRows=expenses.sort((a,b)=>b.amount-a.amount).map((row,index)=>'<tr><td>'+new Intl.NumberFormat('fa-IR').format(index+1)+'</td><td>'+escapeHtml(row.date)+'</td><td><span class="tag">'+escapeHtml(row.category)+'</span></td><td>'+escapeHtml(row.desc)+'</td><td>'+money(row.amount)+'</td></tr>').join('')||'<tr><td colspan="5">ریز هزینه‌ای برای این بازه ثبت نشده است.</td></tr>';return '<!doctype html><html dir="rtl" lang="fa"><head><meta charset="utf-8"><base href="'+location.href+'"><style>@font-face{font-family:Daily;src:url("fonts/Vazirmatn-Regular.ttf")}@font-face{font-family:Daily;src:url("fonts/Vazirmatn-Bold.ttf");font-weight:700}*{box-sizing:border-box}body{margin:0;background:#f5f8ff;color:#17305b;font-family:Daily,Tahoma,sans-serif}.page{max-width:850px;margin:auto;padding:38px}.head{color:#fff;background:linear-gradient(135deg,#1d4ed8,#4f8dfd);padding:30px;border-radius:22px}.brand{font-size:26px;font-weight:700}.sub{font-size:13px;opacity:.88;margin-top:4px}.meta{display:flex;justify-content:space-between;gap:15px;margin-top:24px;font-size:12px}.total{background:#fff;border:1px solid #dce8fc;border-radius:16px;margin:18px 0;padding:17px 20px;display:flex;justify-content:space-between}.total span{color:#617491;font-size:13px}.total strong{color:#2563eb;font-size:20px}h2{font-size:16px;margin:26px 0 10px}table{width:100%;border-collapse:separate;border-spacing:0;background:#fff;border:1px solid #dce8fc;border-radius:15px;overflow:hidden}th{background:#eff5ff;color:#42618e;text-align:right;font-size:12px;padding:12px}td{padding:12px;border-top:1px solid #e8effa;font-size:11px}td:last-child{color:#2563eb;font-weight:700;white-space:nowrap}.tag{display:inline-block;padding:4px 8px;border-radius:999px;background:#eaf8ef;color:#16803b;font-weight:700;font-size:10px}.time-card{background:#fff;border:1px solid #dce8fc;border-radius:15px;padding:16px}.time-row{display:grid;grid-template-columns:120px 1fr 78px;gap:10px;align-items:center;margin:11px 0;font-size:11px}.time-track{height:10px;border-radius:999px;background:#eaf1ff;overflow:hidden}.time-track i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#8b5cf6,#3b82f6)}.time-row b{font-size:10px;color:#5b46be;white-space:nowrap}.empty{color:#7b8da9;font-size:12px}.foot{display:flex;justify-content:space-between;margin-top:24px;padding-top:13px;border-top:1px solid #dce8fc;color:#7b8da9;font-size:10px}@page{size:A4;margin:12mm}@media print{body{background:#fff}.page{max-width:none;padding:0}.head{-webkit-print-color-adjust:exact;print-color-adjust:exact}table,.time-card{break-inside:avoid}}</style></head><body><main class="page"><section class="head"><div class="brand">Daily</div><div class="sub">گزارش حرفه‌ای مدیریت هزینه و برنامه‌ریزی</div><div class="meta"><span>'+escapeHtml(title)+'</span><span>تهیه‌شده در '+fmtJ(new Date())+'</span></div></section><section class="total"><span>جمع هزینه‌های این گزارش</span><strong>'+money(sum)+'</strong></section><h2>خلاصهٔ بازه</h2><table><thead><tr><th>ردیف</th><th>عنوان</th><th>مبلغ</th><th>سهم از کل</th></tr></thead><tbody>'+rows.map(row=>'<tr><td>'+row.n+'</td><td>'+escapeHtml(row.label)+'</td><td>'+money(row.value)+'</td><td>'+row.share+'٪</td></tr>').join('')+'</tbody></table><h2>هزینه بر اساس دسته‌بندی</h2><table><thead><tr><th>ردیف</th><th>دسته‌بندی</th><th>مبلغ</th></tr></thead><tbody>'+categoryRows+'</tbody></table><h2>ریز هزینه‌ها</h2><table><thead><tr><th>ردیف</th><th>تاریخ</th><th>دسته</th><th>شرح هزینه</th><th>مبلغ</th></tr></thead><tbody>'+detailRows+'</tbody></table><h2>نمودار زمان موردنیاز کارها</h2><section class="time-card">'+timeChart(timeRows)+'</section><footer class="foot"><span>Daily — تقویم دیجیتال کایلو</span><span>گزارش شخصی و محرمانه</span></footer></main></body></html>'}function downloadFile(content,type,name){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}function xmlText(value){return String(value??'').replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}function excelSheet(name,headers,rows){return '<Worksheet ss:Name="'+xmlText(name)+'"><Table>'+headers.map((head,index)=>'<Column ss:Width="'+(index===0?55:index===1?210:130)+'"/>').join('')+'<Row>'+headers.map(head=>'<Cell ss:StyleID="h"><Data ss:Type="String">'+xmlText(head)+'</Data></Cell>').join('')+'</Row>'+rows.map(row=>'<Row>'+row.map((value,index)=>'<Cell ss:StyleID="'+(index===0?'c':String(headers[index]).includes('مبلغ')?'m':'')+'"><Data ss:Type="'+(typeof value==='number'?'Number':'String')+'">'+xmlText(value)+'</Data></Cell>').join('')+'</Row>').join('')+'</Table></Worksheet>'}function downloadReport(type,items,title){const html=professionalReport(title,items),rows=reportRows(items),expenses=exportExpenses(items),categories=exportCategories(expenses),timeRows=exportTimeRows(title);if(type==='pdf'){const popup=window.open('','_blank','width=900,height=760');if(!popup){alert('برای خروجی PDF اجازهٔ باز شدن پنجره را بدهید.');return}popup.document.open();popup.document.write(html);popup.document.close();popup.focus();setTimeout(()=>popup.print(),500);return}if(type==='word'){downloadFile('﻿'+html,'application/msword;charset=utf-8','Daily-professional-report.doc');return}const xml='<?xml version="1.0" encoding="utf-8"?><?mso-application progid="Excel.Sheet"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="h"><Font ss:Bold="1" ss:Color="#1E3A5F"/><Interior ss:Color="#EAF1FF" ss:Pattern="Solid"/></Style><Style ss:ID="m"><NumberFormat ss:Format="#,##0 &quot;تومان&quot;"/><Font ss:Bold="1" ss:Color="#2563EB"/></Style><Style ss:ID="c"><Alignment ss:Horizontal="Center"/></Style></Styles>'+excelSheet('خلاصه',['ردیف','عنوان','مبلغ','سهم از کل'],rows.map(row=>[row.n,row.label,row.value,row.share+'٪']))+excelSheet('دسته‌بندی‌ها',['ردیف','دسته‌بندی','مبلغ'],categories.map((row,index)=>[index+1,row.label,row.value]))+excelSheet('ریز هزینه‌ها',['ردیف','تاریخ','دسته‌بندی','شرح هزینه','مبلغ'],expenses.map((row,index)=>[index+1,row.date,row.category,row.desc,row.amount]))+excelSheet('زمان کارها',['ردیف','عنوان','زمان (ساعت)','نمودار زمان'],timeRows.map((row,index)=>[index+1,row.label,row.value,'█'.repeat(Math.max(1,Math.round(row.value/Math.max(...timeRows.map(item=>item.value),1)*18)))]))+'</Workbook>';downloadFile(xml,'application/vnd.ms-excel;charset=utf-8','Daily-detailed-report.xls')}
function renderReport(){const week=Array.from({length:7},(_,i)=>{const d=startOfWeek(cursor);d.setDate(d.getDate()+i);const data=getData(key(d));return{label:dayNames[i],value:total(data),expenses:expensesFromData(data,fmtJ(d))}}),month=jalaliMonthWeeks(),daily=reportDailyCategories(),j=toJalali(cursor.getFullYear(),cursor.getMonth()+1,cursor.getDate());const sets={month:{title:'هزینه کل ماه '+j[0]+'/'+pad(j[1]),items:month,scope:'month'},week:{title:'هزینه‌های هفته',items:week,scope:'week'},day:{title:'هزینه‌های روز '+fmtJ(cursor),items:daily,scope:'day'}};let active='month';const paint=()=>{const set=sets[active];$('#reportContent').innerHTML='<section class="report-panel"><div class="chart-title">'+set.title+'</div><div class="bar-chart">'+chartHtml(set.items,set.scope)+'</div></section>';document.querySelectorAll('.report-bar').forEach(bar=>bar.onclick=()=>{const item=set.items[Number(bar.dataset.index)];showCategoryReport(item,item.label)});animateCharts();document.querySelectorAll('.report-mode button').forEach(button=>button.classList.toggle('active',button.dataset.mode===active));$('#reportExportPdf').onclick=()=>downloadReport('pdf',set.items,set.title);$('#reportExportWord').onclick=()=>downloadReport('word',set.items,set.title);$('#reportExportExcel').onclick=()=>downloadReport('excel',set.items,set.title)};$('#appShell').innerHTML='<section class="report-page"><div class="page-head"><div><div class="eyebrow">Daily</div><h2>گزارش هزینه‌ها</h2><p class="muted">ماه ← هفته ← روز؛ برای دیدن جزئیات دسته‌بندی روی هر ستون بزنید.</p></div><div class="page-actions"><button id="themeBtn" class="tool-btn">☾</button><button id="backBtn" class="back-btn">بازگشت</button></div></div><section class="report-summary-tabs"><div class="report-mode"><button data-mode="month" class="active"><span>هزینه کل ماه</span><strong>'+money(month.reduce((sum,item)=>sum+item.value,0))+'</strong></button><button data-mode="week"><span>هزینه‌های هفتگی</span><strong>'+money(week.reduce((sum,item)=>sum+item.value,0))+'</strong></button><button data-mode="day"><span>هزینه‌های روزانه</span><strong>'+money(daily.reduce((sum,item)=>sum+item.value,0))+'</strong></button></div><div class="report-exports"><button id="reportExportPdf">PDF</button><button id="reportExportWord">Word</button><button id="reportExportExcel">Excel</button></div></section><div id="reportContent"></div></section>';document.querySelectorAll('.report-mode button').forEach(button=>button.onclick=()=>{active=button.dataset.mode;paint()});$('#backBtn').onclick=renderHome;$('#themeBtn').onclick=toggleTheme;paint()}
function showDayPreview(d){const data=getData(key(d));$('#previewTitle').textContent=`${new Intl.DateTimeFormat('fa-IR',{weekday:'long'}).format(d)} · ${fmtJ(d)}`;$('#previewDate').textContent=fmtG(d);const tasks=$('#previewTasks'),expenses=$('#previewExpenses');tasks.innerHTML=data.tasks.filter(t=>t.text).map(t=>`<div class="preview-row ${t.done?'done':''}"><span>${t.starred?'★ ':''}${t.done?'✓':'○'} ${t.text}</span>${t.duration?'<b class="preview-task-duration">'+t.duration+'</b>':''}</div>`).join('')||'<div class="preview-row">کاری ثبت نشده</div>';expenses.innerHTML=data.expenses.filter(e=>e.desc||e.amount).map(e=>`<div class="preview-row preview-expense"><span>${e.desc||'هزینه'}${e.category?' · '+e.category:''}</span><strong>${money(e.amount)}</strong></div>`).join('')||'<div class="preview-row">هزینه‌ای ثبت نشده</div>';$('#previewTotal').textContent='کل: '+money(total(data));$('#previewNote').textContent=data.note||'یادداشتی ثبت نشده است.';$('#previewEditBtn').onclick=()=>{activeDate=new Date(d);$('#dayPreviewModal').classList.add('hidden');renderDay()};$('#dayPreviewModal').classList.remove('hidden')}
function showUpdates(){const pop=$('#updatePopover');localStorage.setItem('daily-last-update','۲.۱.۹');pop.innerHTML=`<div class="update-popover-title">بروزرسانی‌های Daily</div>${updates.map(u=>`<button class="update-link" data-version="${u.version}">نسخه ${u.version}<span>‹</span></button>`).join('')}`;pop.classList.remove('hidden');$('#updatesBtn i')?.remove();pop.querySelectorAll('.update-link').forEach(btn=>btn.onclick=()=>{pop.classList.add('hidden');renderUpdateDetails(btn.dataset.version)})}
function renderUpdateDetails(version){const update=updates.find(u=>u.version===version)||updates[0];$('#appShell').innerHTML=`<section class="detail-page update-page"><div class="page-head"><div><div class="eyebrow">Daily</div><h2>نسخه ${update.version}</h2><p class="muted">${update.title}</p></div><div class="page-actions"><button id="themeBtn" class="tool-btn">☾</button><button id="backBtn" class="back-btn">بازگشت</button></div></div><section class="editor-card update-details"><h3>جزئیات بروزرسانی</h3><ul>${update.details.map(d=>`<li>${d}</li>`).join('')}</ul></section></section>`;$('#backBtn').onclick=renderHome;$('#themeBtn').onclick=toggleTheme}
function buildCalendar(){const y=calendarCursor.getFullYear(),m=calendarCursor.getMonth(),j=toJalali(y,m+1,1);$('#calendarMonth').textContent=`${j[0]}/${pad(j[1])}`;const grid=$('#calendarGrid');grid.innerHTML='';dayNames.forEach(n=>{const c=document.createElement('div');c.className='cal-cell cal-head';c.textContent=n;grid.appendChild(c)});const first=new Date(y,m,1),offset=(first.getDay()+1)%7,days=new Date(y,m+1,0).getDate(),todayKey=key(new Date());for(let i=0;i<offset;i++){const blank=document.createElement('div');blank.className='cal-blank';grid.appendChild(blank)}for(let d=1;d<=days;d++){const date=new Date(y,m,d),j2=toJalali(y,m+1,d),isToday=key(date)===todayKey,c=document.createElement('button');c.type='button';c.className='cal-cell'+(isToday?' today':'');c.innerHTML=`${isToday?'<em>امروز</em>':''}<strong>${new Intl.NumberFormat('fa-IR').format(j2[2])}</strong><small>${j2[0]}/${pad(j2[1])}/${pad(j2[2])}</small>`;c.onclick=()=>{calendarCursor=new Date(date);$('#calendarModal').classList.add('hidden');cursor=new Date(date);renderHome()};grid.appendChild(c)}}
function toggleTheme(){document.body.classList.toggle('dark');localStorage.setItem('daily-theme',document.body.classList.contains('dark')?'dark':'light')}
document.addEventListener('click',e=>{const pop=$('#updatePopover');if(!pop.classList.contains('hidden')&&!pop.contains(e.target)&&!e.target.closest('#updatesBtn'))pop.classList.add('hidden')});initializeApp();
